import re,csv,json,collections,datetime
def tab(n):
    rows=list(csv.reader(open(f'sheets/{n}.csv',encoding='utf-8-sig',newline='')))
    hi=next(i for i,r in enumerate(rows) if len(r)>1 and r[1].strip())
    hdr=[h.split('\n')[-1].strip() for h in rows[hi]]; hdr[0]=hdr[0].split('. ')[-1].strip()
    return [dict(zip(hdr,r)) for r in rows[hi+1:] if any(x.strip() for x in r)]

allc=json.load(open('claims.json'))
trips={r['Trip reference']:r for r in tab('Trips')}
mp={r['Expense reference']:r for r in tab('Merchant_payments')}
fx={(r['Rate date'],r['Currency']):r for r in tab('FX')}
caps={(r['Destination'],r['Category']):r for r in tab('Caps')}
tc=tab('Travel_cancellations')
fa=tab('Finance_activity')
rl=tab('Review_ledger')

t=open('pdf/receipts.txt',encoding='utf-8',errors='replace').read()
rec={}
for blk in re.findall(r'Receipt reference:.*?Issued date:\s*\S+',t,re.S):
    g=dict(re.findall(r'(Receipt reference|Expense reference|Employee|Trip reference|Category|Currency|Gross amount|Documented units|Issued date):\s*(\S+)',blk))
    rec[g['Expense reference']]=g

RECOG={'transport','conference','lodging','meals'}
def deadline(end):
    y,m,d=map(int,end.split('-')); m+=2
    if m>12: m-=12; y+=1
    import calendar
    d=min(d,calendar.monthrange(y,m)[1])
    return f"{y:04d}-{m:02d}-{d:02d}"

# cancellations: confirmed processes by trip/permit
conf={}; reqd={}
for r in tc:
    key=r['Cancellation reference']
    if r['Action']=='confirmed': conf[key]=r
    else: reqd[key]=r
cancel_by_trip=collections.defaultdict(list)
for k,r in conf.items(): cancel_by_trip[r['Trip reference']].append(r)

fa_by_claim=collections.defaultdict(list)
for r in fa: fa_by_claim[r['Claim reference']].append(r)
rl_by_claim=collections.defaultdict(list)
for r in rl:
    if r['Subject type']=='claim': rl_by_claim[r['Subject reference']].append(r)

blockers=collections.defaultdict(list)   # claim_id -> list of (kind, detail)
for c in allc:
    cid=c['claim_id']; tr=trips.get(c['trip'])
    cov=(c['exception'] or {}).get('Covered issues','None')
    for l in c['lines']:
        g=rec.get(l['cost_id'])
        if not g: blockers[cid].append(('missing_receipt',l['cost_id'])); continue
        cat=g['Category']
        if cat not in RECOG and cat!='personal':
            blockers[cid].append(('unknown_category',f"{l['cost_id']}={cat}"))
        pay=mp.get(l['cost_id'])
        if not pay: blockers[cid].append(('no_payment_proof',l['cost_id']))
        else:
            if pay['Currency']!='EUR' and (pay['Paid date'],pay['Currency']) not in fx:
                blockers[cid].append(('missing_fx',f"{l['cost_id']}={pay['Currency']}@{pay['Paid date']}"))
            if cat in ('lodging','meals'):
                dest=tr['Destination'] if tr else '?'
                if (dest,cat) not in caps:
                    blockers[cid].append(('missing_cap',f"{l['cost_id']}={cat}@{dest}"))
    # deadline
    if tr:
        dl=deadline(tr['End date'])
        if c['submitted']>dl:
            if 'Late filing' not in cov: blockers[cid].append(('late_filing',f"sub={c['submitted']} dl={dl}"))
    # cancellation
    for r in cancel_by_trip.get(c['trip'],[]):
        if 'Travel cancellation' not in cov:
            blockers[cid].append(('travel_cancellation',f"{r['Cancellation reference']}/{r['Cancelled subject']}"))
    # review outcomes
    for r in rl_by_claim.get(cid,[]):
        if r['Outcome']!='approve': blockers[cid].append((f"review_{r['Outcome']}",f"{r['Decision reference']}"))
    # finance anomalies
    for r in fa_by_claim.get(cid,[]):
        if r['Activity type'] in ('failed','cancellation_requested','cancelled','adjustment','refund','resolution','retry_authorized'):
            blockers[cid].append(('finance_'+r['Activity type'],r['Activity reference']))

ids=sorted({c['claim_id'] for c in allc},key=lambda x:(len(x),x))
blocked=[i for i in ids if blockers[i]]
print("distinct claim_ids:",len(ids))
print("claims WITH >=1 blocker:",len(blocked))
print("claims with NO blocker :",len(ids)-len(blocked))
print("\nblocker kind totals:",dict(sorted(collections.Counter(k for v in blockers.values() for k,_ in v).items())))
print("\n=== blocked claims detail ===")
for i in blocked:
    print(f"  {i:6} ", "; ".join(f"{k}({d})" for k,d in blockers[i]))
json.dump({k:v for k,v in blockers.items()},open('blockers.json','w'),indent=1)
