def dump_claim(cid, show_page=True):
    c = claims[cid]
    print(json.dumps(c, indent=2, ensure_ascii=False))
    if show_page:
        print("\n--- source claim page (retained PDF text) ---")
        print(claim_page(cid).strip())
    for l in c["lines"]:
        rcp = receipts.get(l["cost_id"])
        if rcp:
            print(f"\n--- receipt {rcp['Receipt reference']} (retained) ---")
            for k in ("Expense reference", "Employee", "Trip reference", "Category",
                      "Currency", "Gross amount", "Documented units", "Issued date"):
                print(f"    {k:20} {rcp[k]}")
        p = pays.get(l["cost_id"])
        print(f"\n--- merchant payment for {l['cost_id']} ---")
        if p:
            for k in ("Transaction reference", "Employee ID", "Trip reference",
                      "Currency", "Gross amount", "Paid date", "Payment status"):
                print(f"    {k:22} {p[k]}")
        else:
            print("    NONE - no settled merchant transaction exists for this cost")
    t = trips.get(c["trip_id"])
    if t:
        print(f"\n--- trip {c['trip_id']} ---")
        for k in ("Employee ID", "Destination", "International", "Start date",
                  "End date", "First commitment date", "Estimate (EUR)",
                  "Permit reference", "Trip revision"):
            print(f"    {k:22} {t[k]}")
    dec = [r for r in rl if r["Subject type"] == "claim"
           and r["Subject reference"] == cid and r["Revision"] == str(c["revision"])]
    print(f"\n--- claim review decisions (revision {c['revision']}) ---")
    for r in dec:
        print(f"    {r['Decision reference']:38} b{r['Arrival batch']} "
              f"roles={r['Review roles'].replace(chr(10), '+'):24} "
              f"{r['Reviewer']:9} {r['Outcome']}")
    if not dec:
        print("    NONE")
    ev = [r for r in fa if r["Claim reference"] == cid]
    print("\n--- finance activity for this claim (all batches, for context) ---")
    for r in ev:
        print(f"    b{r['Arrival batch']} {r['Activity reference']:18} "
              f"{r['Activity type']:22} req={r['Request reference']:9} "
              f"amount={r['Amount (EUR)'] or '-'}")
    print("\n--- request emitted in batch 1 ---")
    print("    " + (json.dumps(requests[cid], ensure_ascii=False)
                    if cid in requests else "NONE"))


